SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS `poi_attractions`;
CREATE TABLE `poi_attractions` (
  `id` bigint unsigned NOT NULL COMMENT 'id',
  `dest_id` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '目的地id',
  `country_code` char(2) COLLATE utf8mb4_general_ci NOT NULL COMMENT '国家码',
  `name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '中文名称',
  `name_en` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '英文名',
  `alias` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '别名',
  `suggested_duration` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '推荐游玩时长：单位：分钟，如60-120',
  `tags` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标签，用|分割',
  `lng` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '经度',
  `lat` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '纬度',
  `coord_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '坐标系',
  `score` decimal(10,1) NOT NULL DEFAULT '0.0' COMMENT '评分',
  `open_time` json DEFAULT NULL COMMENT '开关门时间',
  `address` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '地址',
  `introduction` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '简介',
  `phone` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电话',
  `head_image` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '景点头图',
  `comment_score` decimal(10,1) NOT NULL DEFAULT '0.0' COMMENT '评论评分',
  `ta_comment_num` int NOT NULL DEFAULT '0' COMMENT 'tripadvisor评论数',
  `favorite_num` int NOT NULL DEFAULT '0' COMMENT '收藏数',
  `hot_score` decimal(10,1) NOT NULL DEFAULT '0.0' COMMENT '热度评分',
  `source_id` bigint unsigned NOT NULL COMMENT '源id',
  `sid` int unsigned NOT NULL COMMENT '供应商id',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0正常，1失效',
  `created_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '变更时间',
  PRIMARY KEY (`id`),
  KEY `idx_dest_id` (`dest_id`),
  KEY `idx_country_code` (`country_code`),
  KEY `uk_source_id_sid` (`source_id`,`sid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

